-- Frozen synthetic archive fixture. Do not generate from migrations during tests.
PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TABLE owners (id TEXT PRIMARY KEY);
CREATE TABLE conversations (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES owners(id), created_at TEXT NOT NULL, UNIQUE(owner, id));
CREATE TABLE active_conversations (owner TEXT PRIMARY KEY REFERENCES owners(id), conversation TEXT NOT NULL, FOREIGN KEY(owner, conversation) REFERENCES conversations(owner, id) ON DELETE CASCADE);
CREATE TABLE exchanges (sequence INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, owner TEXT NOT NULL, conversation TEXT NOT NULL, created_at TEXT NOT NULL, origin TEXT NOT NULL CHECK(origin IN ('human','automatic')), user_text TEXT NOT NULL, assistant_text TEXT NOT NULL, tool_names TEXT NOT NULL, FOREIGN KEY(owner, conversation) REFERENCES conversations(owner, id) ON DELETE CASCADE);
CREATE TABLE summaries (id TEXT PRIMARY KEY, owner TEXT NOT NULL, conversation TEXT NOT NULL, through_sequence INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, payload TEXT NOT NULL, FOREIGN KEY(owner,conversation) REFERENCES conversations(owner,id) ON DELETE CASCADE, UNIQUE(conversation,through_sequence));
CREATE TABLE notes (id TEXT PRIMARY KEY, summary TEXT NOT NULL REFERENCES summaries(id) ON DELETE CASCADE, owner TEXT NOT NULL, conversation TEXT NOT NULL, text TEXT NOT NULL, kind TEXT NOT NULL, scope TEXT NOT NULL, status TEXT NOT NULL, sources TEXT NOT NULL);
CREATE TABLE summary_jobs (conversation TEXT PRIMARY KEY, owner TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, retry_at REAL NOT NULL DEFAULT 0, last_served INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(owner,conversation) REFERENCES conversations(owner,id) ON DELETE CASCADE);
CREATE TABLE recall_blocks (owner TEXT NOT NULL, conversation TEXT PRIMARY KEY REFERENCES conversations(id) ON DELETE CASCADE);
CREATE TABLE chunks (id INTEGER PRIMARY KEY, exchange TEXT NOT NULL REFERENCES exchanges(id) ON DELETE CASCADE, owner TEXT NOT NULL, conversation TEXT NOT NULL, created_at TEXT NOT NULL, text TEXT NOT NULL, superseded INTEGER NOT NULL DEFAULT 0);
CREATE VIRTUAL TABLE chunks_fts USING fts5(text, content='chunks', content_rowid='id');
CREATE TABLE embedding_models (id TEXT PRIMARY KEY, dimensions INTEGER NOT NULL);
CREATE TABLE embedding_vectors (chunk INTEGER NOT NULL REFERENCES chunks(id) ON DELETE CASCADE, model TEXT NOT NULL REFERENCES embedding_models(id), text_hash TEXT NOT NULL, vector BLOB NOT NULL, PRIMARY KEY(chunk,model));
CREATE TABLE memory_policy (owner TEXT PRIMARY KEY REFERENCES owners(id), private INTEGER NOT NULL DEFAULT 0 CHECK(private IN (0,1)), epoch INTEGER NOT NULL DEFAULT 0);
CREATE TABLE memory_details (owner TEXT NOT NULL REFERENCES owners(id), label TEXT NOT NULL, text TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(owner,label));
CREATE TABLE detail_uses (owner TEXT NOT NULL, label TEXT NOT NULL, conversation TEXT NOT NULL, FOREIGN KEY(owner,label) REFERENCES memory_details(owner,label) ON DELETE CASCADE, FOREIGN KEY(owner,conversation) REFERENCES conversations(owner,id) ON DELETE CASCADE, PRIMARY KEY(owner,label,conversation));
CREATE TABLE companion_topics (owner TEXT NOT NULL, conversation TEXT NOT NULL, blocked INTEGER NOT NULL DEFAULT 0, offered_at TEXT, PRIMARY KEY(owner,conversation), FOREIGN KEY(owner,conversation) REFERENCES conversations(owner,id) ON DELETE CASCADE);
CREATE TABLE conversation_uses (owner TEXT NOT NULL, source TEXT NOT NULL, target TEXT NOT NULL, PRIMARY KEY(owner,source,target), FOREIGN KEY(owner,source) REFERENCES conversations(owner,id) ON DELETE CASCADE, FOREIGN KEY(owner,target) REFERENCES conversations(owner,id) ON DELETE CASCADE);
CREATE TABLE memory_facts (id TEXT PRIMARY KEY, owner TEXT NOT NULL, fact_key TEXT NOT NULL, value TEXT NOT NULL, kind TEXT NOT NULL, scope TEXT NOT NULL, lifetime TEXT NOT NULL, importance TEXT NOT NULL, status TEXT NOT NULL, source TEXT NOT NULL REFERENCES exchanges(id) ON DELETE CASCADE, evidence TEXT NOT NULL, supersedes TEXT REFERENCES memory_facts(id) ON DELETE SET NULL, detail_label TEXT, status_before_supersession TEXT, FOREIGN KEY(owner,detail_label) REFERENCES memory_details(owner,label) ON DELETE CASCADE);
CREATE TABLE detail_supersessions (owner TEXT NOT NULL, label TEXT NOT NULL, PRIMARY KEY(owner,label), FOREIGN KEY(owner,label) REFERENCES memory_details(owner,label) ON DELETE CASCADE);
CREATE TABLE memory_topics (id TEXT PRIMARY KEY, owner TEXT NOT NULL, label TEXT NOT NULL, scope TEXT NOT NULL, source TEXT NOT NULL REFERENCES exchanges(id) ON DELETE CASCADE, UNIQUE(owner,id));
CREATE TABLE memory_attention (topic TEXT NOT NULL REFERENCES memory_topics(id) ON DELETE CASCADE, source TEXT NOT NULL REFERENCES exchanges(id) ON DELETE CASCADE, engaged INTEGER NOT NULL, status TEXT NOT NULL, evidence TEXT NOT NULL, PRIMARY KEY(topic,source));
CREATE TABLE embedding_failures (chunk INTEGER NOT NULL REFERENCES chunks(id) ON DELETE CASCADE, model TEXT NOT NULL REFERENCES embedding_models(id), attempts INTEGER NOT NULL DEFAULT 0, retry_at REAL NOT NULL DEFAULT 0, PRIMARY KEY(chunk,model));
CREATE INDEX conversation_exchanges ON exchanges(conversation, sequence);
CREATE INDEX conversation_notes ON notes(owner,conversation);
CREATE INDEX chunk_sources ON chunks(exchange);
CREATE INDEX fact_selection ON memory_facts(owner,status,scope,lifetime);
CREATE INDEX detail_fact_selection ON memory_facts(owner,detail_label,status);
CREATE INDEX topic_selection ON memory_topics(owner,label);
CREATE TRIGGER chunks_insert AFTER INSERT ON chunks BEGIN INSERT INTO chunks_fts(rowid,text) VALUES (new.id,new.text); END;
CREATE TRIGGER chunks_delete AFTER DELETE ON chunks BEGIN INSERT INTO chunks_fts(chunks_fts,rowid,text) VALUES ('delete',old.id,old.text); END;
